export type OrganizationSettingsFormProps = {
  org: Organization;
  disabled: boolean;
};

type SettingsState = ActionResult<Organization> | null;

export function OrganizationSettingsForm(props: OrganizationSettingsFormProps) {
  const { org, disabled } = props;

  const [state, submit, pending] = useActionState<SettingsState, FormData>(
    async (_previous, formData) => {
      const logoUrl = String(formData.get("logoUrl") ?? "").trim();

      const parsed = updateOrganizationSchema.safeParse({
        orgId: org.id,
        name: String(formData.get("name") ?? ""),
        logoUrl: logoUrl.length === 0 ? null : logoUrl,
        settings: {
          allowPublicProjects: formData.get("allowPublicProjects") === "on",
          requireTwoFactor: formData.get("requireTwoFactor") === "on",
          digestHourUtc: Number(formData.get("digestHourUtc") ?? 7),
        },
      });

      if (!parsed.success) {
        return {
          ok: false,
          error: {
            code: "validation_failed",
            message: "Check the fields below.",
            fieldErrors: fieldErrorsFromZod(parsed.error),
          },
        };
      }

      return updateOrganizationAction(parsed.data);
    },
    null,
  );

  const fieldErrors = state?.ok === false ? (state.error.fieldErrors ?? {}) : {};

  return (
    <form action={submit} className="space-y-6">
      {state?.ok === true ? (
        <p className="rounded bg-emerald-50 px-3 py-2 text-sm text-emerald-700">
          Settings saved.
        </p>
      ) : null}
      {state?.ok === false && state.error.code === "forbidden" ? (
        <p role="alert" className="rounded bg-rose-50 px-3 py-2 text-sm text-rose-700">
          Your role does not allow changing organization settings.
        </p>
      ) : null}

      <div className="space-y-1">
        <label htmlFor="name" className="text-sm font-medium">
          Organization name
        </label>
        <input
          id="name"
          name="name"
          defaultValue={org.name}
          disabled={disabled}
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
        />
        {fieldErrors.name !== undefined ? (
          <p className="text-xs text-rose-600">{fieldErrors.name[0]}</p>
        ) : null}
      </div>

      <div className="space-y-1">
        <label htmlFor="logoUrl" className="text-sm font-medium">
          Logo URL
        </label>
        <input
          id="logoUrl"
          name="logoUrl"
          type="url"
          defaultValue={org.logoUrl ?? ""}
          disabled={disabled}
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
        />
      </div>

      <div className="space-y-1">
        <label htmlFor="digestHourUtc" className="text-sm font-medium">
          Digest hour (UTC)
        </label>
        <input
          id="digestHourUtc"
          name="digestHourUtc"
          type="number"
          min={0}
          max={23}
          defaultValue={org.settings.digestHourUtc}
          disabled={disabled}
          className="w-24 rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
        />
        <p className="text-xs text-slate-500">
          The daily digest job runs once an hour and picks up organizations whose
          hour has come round.
        </p>
      </div>

      <label className="flex items-center gap-2 text-sm">
        <input
          type="checkbox"
          name="allowPublicProjects"
          defaultChecked={org.settings.allowPublicProjects}
          disabled={disabled}
        />
        Allow projects to be made public
      </label>

      <label className="flex items-center gap-2 text-sm">
        <input
          type="checkbox"
          name="requireTwoFactor"
          defaultChecked={org.settings.requireTwoFactor}
          disabled={disabled}
        />
        Require two-factor authentication
      </label>

      <button
        type="submit"
        disabled={disabled || pending}
        className="rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-60"
      >
        {pending ? "Saving…" : "Save settings"}
      </button>
    </form>
  );
}

/**
 * Primitive identifier and envelope types shared by every Taskflow domain type.
 *
 * Every entity in Taskflow uses opaque branded string ids so that an `IssueId`
 * can never be silently passed where a `ProjectId` is expected. Ids are ULID
 * strings at runtime; the brand exists only at the type level.
 */

declare const brand: unique symbol;

/** Attaches a compile-time-only tag to a primitive type. */
export type Branded<T, B extends string> = T & { readonly [brand]: B };

export type UserId = Branded<string, "UserId">;
export type OrgId = Branded<string, "OrgId">;
export type ProjectId = Branded<string, "ProjectId">;
export type IssueId = Branded<string, "IssueId">;
export type CommentId = Branded<string, "CommentId">;
export type MemberId = Branded<string, "MemberId">;
export type NotificationId = Branded<string, "NotificationId">;
export type ActivityId = Branded<string, "ActivityId">;
export type InvitationId = Branded<string, "InvitationId">;
export type LabelId = Branded<string, "LabelId">;
export type AttachmentId = Branded<string, "AttachmentId">;
export type SubscriptionId = Branded<string, "SubscriptionId">;
export type SessionId = Branded<string, "SessionId">;
export type WebhookId = Branded<string, "WebhookId">;

/** Union of every branded id used in the app, for generic id helpers. */
export type AnyId =
  | UserId
  | OrgId
  | ProjectId
  | IssueId
  | CommentId
  | MemberId
  | NotificationId
  | ActivityId
  | InvitationId
  | LabelId
  | AttachmentId
  | SubscriptionId
  | SessionId
  | WebhookId;

/** ISO-8601 timestamp string as stored in SQLite text columns. */
export type IsoTimestamp = Branded<string, "IsoTimestamp">;

/** Rows carrying the standard created/updated bookkeeping columns. */
export interface Timestamps {
  readonly createdAt: IsoTimestamp;
  readonly updatedAt: IsoTimestamp;
}

/**
 * Soft-delete marker. `archivedAt === null` means the row is live. Repositories
 * must filter on this via the helpers in `src/lib/soft-delete.ts` rather than
 * writing the predicate by hand.
 */
export interface SoftDeletable {
  readonly archivedAt: IsoTimestamp | null;
}

/** Rows that belong to exactly one tenant. Enforced by `src/lib/tenant.ts`. */
export interface TenantScoped {
  readonly orgId: OrgId;
}

export type SortDirection = "asc" | "desc";

export interface SortSpec<TField extends string = string> {
  readonly field: TField;
  readonly direction: SortDirection;
}

/** Cursor pagination request shared by every repository `list*` method. */
export interface PageRequest {
  readonly limit: number;
  readonly cursor?: string | null;
}

/** Cursor pagination response shared by every repository `list*` method. */
export interface Page<T> {
  readonly items: readonly T[];
  readonly nextCursor: string | null;
  readonly total: number;
}

/** Options accepted by every soft-delete-aware repository read. */
export interface ArchiveScope {
  readonly includeArchived?: boolean;
}

export function makePage<T>(
  items: readonly T[],
  nextCursor: string | null,
  total: number,
): Page<T> {
  return { items, nextCursor, total };
}

export function toIsoTimestamp(value: Date | string): IsoTimestamp {
  const date = typeof value === "string" ? new Date(value) : value;
  return date.toISOString() as IsoTimestamp;
}
/** Relative formatting, overdue detection and the digest window. */
import { describe, expect, it } from "vitest";
import {
  addDays,
  digestWindow,
  formatDate,
  formatRelative,
  isOverdue,
  now,
  parseIso,
} from "@/lib/date";
import type { IsoTimestamp } from "@/types/common";

const REFERENCE = new Date("2026-03-15T12:00:00.000Z");
const iso = (value: string): IsoTimestamp => value as IsoTimestamp;

describe("lib/date", () => {
  it("round-trips now() through parseIso()", () => {
    const stamp = now();
    expect(parseIso(stamp).toISOString()).toBe(stamp);
  });

  it("throws on a malformed timestamp rather than yielding Invalid Date", () => {
    expect(() => parseIso(iso("not-a-date"))).toThrow(RangeError);
  });

  it("formats past distances with an 'ago' suffix", () => {
    expect(formatRelative(iso("2026-03-15T11:59:30.000Z"), REFERENCE)).toBe("just now");
    expect(formatRelative(iso("2026-03-15T11:55:00.000Z"), REFERENCE)).toBe("5 minutes ago");
    expect(formatRelative(iso("2026-03-15T11:00:00.000Z"), REFERENCE)).toBe("1 hour ago");
    expect(formatRelative(iso("2026-03-13T12:00:00.000Z"), REFERENCE)).toBe("2 days ago");
    expect(formatRelative(iso("2026-03-01T12:00:00.000Z"), REFERENCE)).toBe("2 weeks ago");
  });

  it("formats future distances with an 'in' prefix", () => {
    expect(formatRelative(iso("2026-03-15T12:30:00.000Z"), REFERENCE)).toBe("in 30 minutes");
    expect(formatRelative(iso("2026-03-18T12:00:00.000Z"), REFERENCE)).toBe("in 3 days");
  });

  it("renders an absolute date in the requested timezone", () => {
    expect(formatDate(iso("2026-03-15T23:30:00.000Z"))).toBe("15 Mar 2026");
    expect(formatDate(iso("2026-03-15T23:30:00.000Z"), "Asia/Tokyo")).toBe("16 Mar 2026");
  });

  it("treats a null due date as never overdue", () => {
    expect(isOverdue(null, REFERENCE)).toBe(false);
    expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(true);
    expect(isOverdue(iso("2026-03-15T12:00:01.000Z"), REFERENCE)).toBe(false);
  });

  it("adds and subtracts whole days", () => {
    expect(addDays(iso("2026-03-15T12:00:00.000Z"), 3)).toBe("2026-03-18T12:00:00.000Z");
    expect(addDays(iso("2026-03-01T12:00:00.000Z"), -1)).toBe("2026-02-28T12:00:00.000Z");
  });

  it("ends the digest window at today's digest hour once it has passed", () => {
    const window = digestWindow(8, REFERENCE);
    expect(window.end).toBe("2026-03-15T08:00:00.000Z");
    expect(window.start).toBe("2026-03-14T08:00:00.000Z");
  });

  it("falls back to yesterday's window when the digest hour has not arrived", () => {
    const window = digestWindow(20, REFERENCE);
    expect(window.end).toBe("2026-03-14T20:00:00.000Z");
    expect(window.start).toBe("2026-03-13T20:00:00.000Z");
  });

  it("rejects a digest hour outside 0-23", () => {
    expect(() => digestWindow(24, REFERENCE)).toThrow(RangeError);
    expect(() => digestWindow(-1, REFERENCE)).toThrow(RangeError);
  });
});
