              onClick={() => pick(today)}
              className="text-[11px] text-brand-600 hover:underline"
            >
              Today
            </button>
            <button
              type="button"
              onClick={() => {
                onChange(null);
                setOpen(false);
              }}
              className="text-[11px] text-black/50 hover:underline"
            >
              Clear
            </button>
          </div>
        </div>
      ) : null}
    </div>
  );
