/** Absolute calendar rendering, e.g. "12 Mar 2026", in the given timezone. */
export function formatDate(value: IsoTimestamp, timezone = "UTC"): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: timezone,
  }).format(parseIso(value));
}

/** The calendar date of an instant on the workspace's clock. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(parseIso(value));
  const part = (type: Intl.DateTimeFormatPartTypes) =>
    parts.find((value) => value.type === type)!.value;
  return `${part("year").padStart(4, "0")}-${part("month")}-${part("day")}`;
}

function shiftCalendarDate(day: string, days: number): string {
  return addDays(toIsoTimestamp(`${day}T00:00:00.000Z`), days).slice(0, 10);
}

/**
 * Resolve a wall-clock hour using the offsets on either side of that date.
 * A repeated hour has two instants; a skipped hour moves forward by the gap.
 */
function localHourInstants(day: string, hour: number, timeZone: string): number[] {
  const wallTime = parseIso(toIsoTimestamp(`${day}T00:00:00.000Z`)).getTime() + hour * HOUR_MS;
  const formatter = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  });
  const wallTimeAt = (instant: number): number => {
    const parts = formatter.formatToParts(new Date(instant));
    const part = (type: Intl.DateTimeFormatPartTypes) =>
      Number(parts.find((value) => value.type === type)!.value);
    const date = new Date(0);
    date.setUTCFullYear(part("year"), part("month") - 1, part("day"));
    date.setUTCHours(part("hour"), part("minute"), part("second"), 0);
    return date.getTime();
  };

  const offsets = new Set(
    [-2, -1, 0, 1, 2].map((days) => {
      const instant = wallTime + days * DAY_MS;
      return wallTimeAt(instant) - instant;
    }),
  );
  const candidates = [...offsets].map((offset) => wallTime - offset).sort((a, b) => a - b);
  const exact = candidates.filter((instant) => wallTimeAt(instant) === wallTime);
  return exact.length > 0 ? exact : [candidates[candidates.length - 1]];
}

/** Local midnight for a calendar date, including zones that skip midnight. */
export function startOfLocalDate(day: string, timeZone: string): IsoTimestamp {
  return toIsoTimestamp(new Date(localHourInstants(day, 0, timeZone)[0]));
}

/** The UTC instant at which reference's local calendar day began. */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  return startOfLocalDate(localDate(toIsoTimestamp(reference), timeZone), timeZone);
}

/** A due date becomes overdue only after its local calendar day has ended. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < localDate(toIsoTimestamp(reference), timeZone);
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * A calendar-day window ending at the most recent local digest hour. Its
 * elapsed duration can be 23 or 25 hours across a daylight-saving change.
 */
export function digestWindow(
  digestHourUtc: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
  }

  let endDay = localDate(toIsoTimestamp(reference), timeZone);
  let candidates = localHourInstants(endDay, digestHourUtc, timeZone)
    .filter((instant) => instant <= reference.getTime());
  if (candidates.length === 0) {
    endDay = shiftCalendarDate(endDay, -1);
    candidates = localHourInstants(endDay, digestHourUtc, timeZone);
  }
  const end = candidates[candidates.length - 1];
  const start = localHourInstants(shiftCalendarDate(endDay, -1), digestHourUtc, timeZone)[0];

  return {
    start: toIsoTimestamp(new Date(start)),
    end: toIsoTimestamp(new Date(end)),
  };
